// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber) public {
        uint256 payment = 10 ether;
        vm.assume(blockNumber % 15 == 0);
        vm.assume(blockNumber > block.number);

        address caller = address(0xBEEF);
        vm.deal(caller, payment);
        vm.startPrank(caller);
        vm.warp(1);
        vm.roll(blockNumber);
        (bool ok, ) = address(c).call{value: payment}("");
        vm.stopPrank();
        assertTrue(ok && address(c).balance == 0);
    }
}
